import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

// Schema cho phản hồi phân tích camera AI
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Phân tích frame webcam để kiểm tra độ tuân thủ ảnh thẻ bằng Gemini 3 Flash.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  // Always create a new instance inside the function to use the latest API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (!process.env.API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `Phân tích ảnh thẻ sinh trắc học. Trả về JSON.
            Tiêu chí: Mặt nhìn thẳng, mắt mở, miệng đóng, đủ sáng, không bóng đổ mạnh.
            JSON: {isCompliant: boolean, status: 'VALID'|'ADJUSTING'|'INVALID', feedback: string, instruction: string, faceDetected: boolean}.
            'instruction': Câu lệnh tiếng Việt ngắn gọn (VD: "Nâng cằm lên", "Nhìn thẳng camera").` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);
    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Offline Mode', 
      instruction: 'Sẵn sàng', 
      faceDetected: true 
    };
  }
};

/**
 * Xử lý ảnh thẻ bằng AI với các tham số kỹ thuật (Intensity Factors).
 * BẮT BUỘC GIỮ NGUYÊN ĐẶC ĐIỂM SINH TRẮC HỌC.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  // Always create a new instance inside the function to use the latest API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (!process.env.API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  const systemInstructions = [
    "Bạn là chuyên gia chỉnh sửa ảnh thẻ chuyên nghiệp. Thực hiện các thay đổi dựa trên các tham số cường độ (Intensity) từ 0-100.",
    "",
    "### QUY TẮC SINH TRẮC HỌC TUYỆT ĐỐI:",
    "- CẤM THAY ĐỔI cấu trúc xương mặt, hốc mắt, hình dáng mũi và cằm.",
    "- CẤM XÓA nốt ruồi, sẹo, hoặc các đặc điểm định danh vĩnh viễn.",
    "- Duy trì tính nhất quán về ánh sáng giữa khuôn mặt và phông nền mới.",
    "",
    "### CHỈ THỊ CHI TIẾT (DETERMINISTIC):",
    `1. [Thay Phông Nền]: ${bgType.toUpperCase()}`,
    bgType === BackgroundType.WHITE ? "- Hành động: Thay toàn bộ phông nền bằng màu trắng (#FFFFFF)." : 
    bgType === BackgroundType.BLUE ? "- Hành động: Thay toàn bộ phông nền bằng màu xanh chuẩn (#2792ff)." :
    bgType === BackgroundType.GRAY ? "- Hành động: Thay toàn bộ phông nền bằng màu xám (#d1d5db)." :
    "- Hành động: BỎ QUA tác vụ này, giữ nguyên nền gốc.",
    "",
    `2. [Thay Trang Phục]: ${clothingPrompt ? `Intensity: 100, Item: ${clothingPrompt}` : 'Intensity: 0'}`,
    clothingPrompt ? `- Hành động: Thay trang phục thành "${clothingPrompt}". Đảm bảo cổ áo khít tự nhiên.` : "- Hành động: BỎ QUA tác vụ này.",
    "",
    `3. [Làm Mịn Da]: Intensity ${beautySettings.smoothSkin}/100`,
    beautySettings.smoothSkin === 0 ? "- Hành động: BỎ QUA hoàn toàn, không can thiệp vào da." : `- Hành động: Làm mịn da ở mức ${beautySettings.smoothSkin}%. Giữ lại vân da tự nhiên.`,
    "",
    `4. [Xóa Khuyết Điểm]: ${beautySettings.removeBlemishes ? 'Intensity: 100' : 'Intensity: 0'}`,
    beautySettings.removeBlemishes ? "- Hành động: Xóa các đốm mụn tạm thời. GIỮ LẠI nốt ruồi và sẹo." : "- Hành động: BỎ QUA tác vụ này.",
    "",
    `5. [Son Môi]: Màu "${beautySettings.lipstickColor}", Intensity ${beautySettings.lipstickIntensity}/100`,
    beautySettings.lipstickIntensity === 0 ? "- Hành động: BỎ QUA, không thêm màu môi." : `- Hành động: Áp dụng màu ${beautySettings.lipstickColor} with cường độ ${beautySettings.lipstickIntensity}%.`,
    "",
    `6. [Má Hồng]: Màu "${beautySettings.blushColor}", Intensity ${beautySettings.blushIntensity}/100`,
    beautySettings.blushIntensity === 0 ? "- Hành động: BỎ QUA, không thêm má hồng." : `- Hành động: Áp dụng màu má hồng ${beautySettings.blushColor} with cường độ ${beautySettings.blushIntensity}%.`,
    "",
    `7. [Tạo Khối]: Intensity ${beautySettings.contourIntensity}/100`,
    beautySettings.contourIntensity === 0 ? "- Hành động: BỎ QUA, không thay đổi khối khuôn mặt." : `- Hành động: Nhấn nhẹ khối ở mức ${beautySettings.contourIntensity}%.`,
    "",
    `8. [Chân Mày]: Intensity ${beautySettings.eyebrowIntensity}/100`,
    beautySettings.eyebrowIntensity === 0 ? "- Hành động: BỎ QUA, giữ nguyên chân mày." : `- Hành động: Định hình chân mày ở mức ${beautySettings.eyebrowIntensity}%.`,
    "",
    `9. [Làm Dày Tóc & Đổi Màu]: Intensity ${beautySettings.hairVolume}/100, Màu: ${beautySettings.hairColor || 'Màu gốc'}`,
    beautySettings.hairVolume === 0 ? "- Hành động: BỎ QUA, không can thiệp tóc." : `- Hành động: Làm dày và gọn tóc ở mức ${beautySettings.hairVolume}%, nhuộm màu tóc sang "${beautySettings.hairColor}".`,
    "",
    "KẾT QUẢ: Chỉ trả về dữ liệu ảnh PNG chất lượng cao (Base64)."
  ].join("\n");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Fixed model name from gemini-2.5-pro-image
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/PNG', data: cleanBase64 } },
          { text: systemInstructions }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/PNG;base64,${part.inlineData.data}`;
        }
      }
    }
    throw new Error("AI không trả về dữ liệu ảnh.");

  } catch (error: any) {
    console.error("Gemini processing error:", error);
    const errorString = JSON.stringify(error);
    if (errorString.includes('429')) {
      throw new Error("AI_QUOTA_EXCEEDED");
    }
    if (errorString.includes('404') || errorString.includes('Requested entity was not found')) {
      throw new Error("MODEL_NOT_FOUND");
    }
    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

// Sub-components
import EditorBackgroundTab from './EditorBackgroundTab';
import EditorClothingTab from './EditorClothingTab';
import EditorMakeupTab from './EditorMakeupTab';
import EditorFilterTab from './EditorFilterTab';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing' | 'makeup';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const getAiSettingsHash = useCallback((s: PhotoSettings) => {
    const beauty = s.beauty;
    return JSON.stringify({
       background: s.background,
       cloth: s.clothingPrompt,
       blemish: beauty.removeBlemishes,
       smooth: beauty.smoothSkin,
       lipCol: beauty.lipstickColor,
       lipInt: beauty.lipstickIntensity,
       blushCol: beauty.blushColor,
       blushInt: beauty.blushIntensity,
       brow: beauty.eyebrowIntensity,
       contour: beauty.contourIntensity,
       hair: beauty.hairVolume,
       hairStyle: beauty.hairStyle,
       hairColor: beauty.hairColor 
    });
  }, []);

  const getRawStateHash = useCallback(() => {
     return JSON.stringify({
       background: BackgroundType.ORIGINAL,
       cloth: undefined,
       blemish: false,
       smooth: 0,
       lipCol: settings.beauty.lipstickColor,
       lipInt: 0,
       blushCol: settings.beauty.blushColor,
       blushInt: 0,
       brow: 0,
       contour: 0,
       hair: 0,
       hairStyle: 'original',
       hairColor: 'original'
     });
  }, [settings.beauty.lipstickColor, settings.beauty.blushColor]);

  const [appliedHash, setAppliedHash] = useState<string>(getRawStateHash());

  const hasPendingAiChanges = useMemo(() => {
    const currentHash = getAiSettingsHash(settings);
    const safeAppliedHash = appliedHash || getRawStateHash();
    return currentHash !== safeAppliedHash;
  }, [settings, appliedHash, getAiSettingsHash, getRawStateHash]);

  const handleApplyAiChanges = useCallback(async () => {
    const currentHash = getAiSettingsHash(settings);
    setIsProcessing(true);
    setLoadingAction("Đang xử lý...");

    try {
      const isDefault = 
        settings.background === BackgroundType.ORIGINAL && 
        !settings.clothingPrompt && 
        !settings.beauty.removeBlemishes && 
        settings.beauty.smoothSkin === 0 &&
        settings.beauty.lipstickIntensity === 0 && 
        settings.beauty.blushIntensity === 0 &&
        settings.beauty.eyebrowIntensity === 0 &&
        settings.beauty.contourIntensity === 0 &&
        settings.beauty.hairVolume === 0 &&
        (settings.beauty.hairStyle === 'original' || !settings.beauty.hairStyle) &&
        (settings.beauty.hairColor === 'original' || !settings.beauty.hairColor || settings.beauty.hairColor === 'Màu gốc');

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(
            originalImage, 
            settings.background, 
            settings.clothingPrompt, 
            settings.beauty, 
            settings.size
        );
        setProcessedUrl(result);
      }
      setAppliedHash(currentHash);
    } catch (err: any) {
      console.error(err);
      if (err.message === 'MODEL_NOT_FOUND' || (err.message && err.message.includes('entity was not found'))) {
        alert("Lỗi kết nối AI (404). Vui lòng chọn lại API Key hợp lệ.");
        if ((window as any).aistudio?.openSelectKey) {
            await (window as any).aistudio.openSelectKey();
        }
      } else if (err.message === 'AI_QUOTA_EXCEEDED') {
        alert("Giới hạn lượt dùng AI đã hết. Vui lòng thử lại sau.");
      } else {
        alert("Lỗi xử lý ảnh: " + (err.message || "Không xác định"));
      }
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  }, [settings, originalImage, getAiSettingsHash]);

  // Handlers passed to sub-components
  const handleBgChange = (bg: BackgroundType) => onUpdateSettings({ ...settings, background: bg });
  const handleClothingClick = (prompt: string) => onUpdateSettings({ ...settings, clothingPrompt: prompt });
  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });

  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);
    let sepia = 0, hue = 0, saturate = 100;
    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) { sepia = skinToneIntensity * 0.3; saturate = 100 - (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.ROSY) { sepia = skinToneIntensity * 0.15; hue = -10; saturate = 100 + (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.FAIR) { saturate = 100 - (skinToneIntensity * 0.1); }
    }
    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  const handleFinish = () => {
    const finishExport = (imgSrc: string) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.src = imgSrc;
        img.onload = () => {
            canvas.width = img.width; canvas.height = img.height;
            if (ctx) { ctx.filter = imageFilters; ctx.drawImage(img, 0, 0, canvas.width, canvas.height); onProcessedImage(canvas.toDataURL('image/png', 1.0)); onNext(); }
        };
    };
    if (hasPendingAiChanges) {
        if (confirm("Có thay đổi chưa áp dụng. Áp dụng ngay?")) {
            handleApplyAiChanges().then(() => finishExport(processedUrl));
        } else { finishExport(processedUrl); }
    } else { finishExport(processedUrl); }
  };

  return (
    <div className="flex flex-col md:flex-row h-screen h-[100dvh] w-full bg-slate-100 overflow-hidden font-sans"
       onMouseUp={() => { isDraggingRef.current = false; }}
       onTouchEnd={() => { isDraggingRef.current = false; }}
    >
      <div className="w-full md:w-[400px] bg-white shadow-2xl z-20 flex flex-col h-[50dvh] md:h-full border-r border-gray-200">
        <div className="p-3 md:p-4 border-b border-gray-100 flex justify-between items-center shrink-0">
          <h2 className="text-lg md:text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600">⚡</span> Chỉnh sửa
          </h2>
          <span className="text-[9px] md:text-[10px] font-bold text-purple-600 bg-purple-50 px-2 py-0.5 rounded-full">ID Photo Booth Pro</span>
        </div>

        <div className="px-3 pt-3 pb-1 md:px-4 md:pt-4 shrink-0">
          <div className="flex bg-gray-100 p-1 rounded-xl overflow-x-auto scrollbar-hide">
            {[
              {id: 'background', label: '1. Nền'},
              {id: 'clothing', label: '2. Áo'},
              {id: 'makeup', label: '3. Makeup'},
              {id: 'beauty', label: '4. Bộ lọc'}
            ].map((tab) => (
               <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 min-w-[65px] py-2 text-[10px] font-bold uppercase rounded-lg transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-brand-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>{tab.label}</button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-5 bg-white scrollbar-hide">
          {activeTab === 'background' && (
            <EditorBackgroundTab config={config} settings={settings} onBgChange={handleBgChange} />
          )}

          {activeTab === 'clothing' && (
            <EditorClothingTab config={config} settings={settings} onClothingClick={handleClothingClick} />
          )}

          {activeTab === 'makeup' && (
            <EditorMakeupTab config={config} settings={settings} onAiBeautyChange={handleAiBeautyChange} />
          )}

          {activeTab === 'beauty' && (
            <EditorFilterTab settings={settings} onClientBeautyChange={handleClientBeautyChange} />
          )}
        </div>

        <div className="p-3 md:p-4 border-t border-gray-200 bg-white space-y-2 shrink-0">
          {hasPendingAiChanges && (
            <button onClick={handleApplyAiChanges} disabled={isProcessing} className="w-full py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-xs shadow-md active:scale-95 disabled:opacity-50">✨ Áp dụng AI</button>
          )}
          <button onClick={handleFinish} disabled={isProcessing} className="w-full py-3 bg-brand-600 text-white rounded-xl font-bold text-sm shadow-lg active:scale-95 disabled:bg-gray-400">Hoàn tất & In</button>
          <button onClick={onRetake} disabled={isProcessing} className="w-full py-2 bg-slate-50 text-slate-500 rounded-xl font-bold text-xs border border-slate-200">Chụp lại</button>
        </div>
      </div>

      <div className="flex-1 bg-slate-200 relative flex items-center justify-center p-4 md:p-8 h-[50dvh] md:h-full">
        {isProcessing && (
          <div className="absolute inset-0 z-30 bg-black/30 backdrop-blur-sm flex items-center justify-center">
            <div className="bg-white p-5 rounded-2xl shadow-2xl flex flex-col items-center">
              <div className="w-8 h-8 border-3 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-3"></div>
              <p className="text-brand-800 font-bold text-xs">{loadingAction}</p>
            </div>
          </div>
        )}
        <div ref={imageContainerRef} className="relative shadow-2xl rounded-sm border-2 border-white bg-white overflow-hidden max-h-full max-w-full cursor-col-resize"
             style={{ aspectRatio: settings.size === PhotoSize.SIZE_5X5 ? '1/1' : '2/3', height: '90%' }}
             onMouseDown={() => { isDraggingRef.current = true; }}
             onTouchStart={() => { isDraggingRef.current = true; }}
             onMouseMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
             onTouchMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.touches[0].clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
        >
          <img src={originalImage} className="absolute inset-0 w-full h-full object-contain pointer-events-none" />
          <div className="absolute inset-0 w-full h-full pointer-events-none" style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}>
             <img src={processedUrl} className="absolute inset-0 w-full h-full object-contain" style={{ filter: imageFilters }} />
          </div>
          <div className="absolute top-0 bottom-0 w-0.5 bg-white z-20 shadow-md" style={{ left: `${sliderPosition}%` }}>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-6 h-6 bg-white rounded-full shadow-lg flex items-center justify-center border border-gray-200 cursor-grab active:cursor-grabbing">
              <div className="w-1 h-3 bg-brand-500 rounded-full"></div>
            </div>
          </div>

          <div className="absolute bottom-2 left-2 text-[8px] font-bold text-white bg-black/40 px-2 py-0.5 rounded uppercase tracking-widest backdrop-blur-sm pointer-events-none">Ảnh Gốc</div>
          <div className="absolute bottom-2 right-2 text-[8px] font-bold text-white bg-brand-600/60 px-2 py-0.5 rounded uppercase tracking-widest backdrop-blur-sm pointer-events-none">Đã xử lý</div>
        </div>
      </div>
    </div>
  );
};

export default ImageEditor;

import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

// Schema cho phản hồi phân tích camera AI
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Phân tích frame webcam để kiểm tra độ tuân thủ ảnh thẻ bằng Gemini 3 Flash.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  // Always create a new instance inside the function to use the latest API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (!process.env.API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `Phân tích ảnh thẻ sinh trắc học. Trả về JSON.
            Tiêu chí: Mặt nhìn thẳng, mắt mở, miệng đóng, đủ sáng, không bóng đổ mạnh.
            JSON: {isCompliant: boolean, status: 'VALID'|'ADJUSTING'|'INVALID', feedback: string, instruction: string, faceDetected: boolean}.
            'instruction': Câu lệnh tiếng Việt ngắn gọn (VD: "Nâng cằm lên", "Nhìn thẳng camera").` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);
    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Offline Mode', 
      instruction: 'Sẵn sàng', 
      faceDetected: true 
    };
  }
};

/**
 * Xử lý ảnh thẻ bằng AI với các tham số kỹ thuật (Intensity Factors).
 * BẮT BUỘC GIỮ NGUYÊN ĐẶC ĐIỂM SINH TRẮC HỌC.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  // Always create a new instance inside the function to use the latest API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (!process.env.API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Xây dựng prompt có cấu trúc Deterministic (Nếu Intensity = 0 thì bỏ qua)
  // FIX: Wrapped instructions in backticks to prevent SyntaxError
  const systemInstructions = [
    "Bạn là chuyên gia chỉnh sửa ảnh thẻ chuyên nghiệp. Thực hiện các thay đổi dựa trên các tham số cường độ (Intensity) từ 0-100.",
    "",
    "### QUY TẮC SINH TRẮC HỌC TUYỆT ĐỐI:",
    "- CẤM THAY ĐỔI cấu trúc xương mặt, hốc mắt, hình dáng mũi và cằm.",
    "- CẤM XÓA nốt ruồi, sẹo, hoặc các đặc điểm định danh vĩnh viễn.",
    "- Duy trì tính nhất quán về ánh sáng giữa khuôn mặt và phông nền mới.",
    "",
    `IMAGE EDITING INSTRUCTIONS (DETERMINISTIC):

1. BACKGROUND REPLACEMENT
Mode: ${bgType}

IF bgType = WHITE:
- Replace the entire background with a SOLID, UNIFORM, FLAT white color.
- Exact color: RGB(255,255,255) / HEX #FFFFFF
- No gradients, no shadows, no texture, no lighting variation.
- Edge must be clean and continuous around hair and shoulders.

IF bgType = BLUE:
- Replace background with SOLID blue.
- Exact color: RGB(39,146,255) / HEX #2792FF
- Flat color only. No gradient, no vignette.

IF bgType = GRAY:
- Replace background with SOLID gray.
- Exact color: RGB(209,213,219) / HEX #D1D5DB

IF bgType = NONE:
- Do NOT modify background in any way.

---

2. CLOTHING REPLACEMENT
Intensity: ${clothingPrompt ? "100" : "0"}

IF enabled:
- Replace clothing with: "${clothingPrompt}"
- Clothing must look neutral, formal, and suitable for ID photos.
- Collar must be natural and realistic.
- Do NOT change body shape or posture.

IF disabled:
- Do NOT alter clothing.

---

3. SKIN SMOOTHING
Intensity: ${beautySettings.smoothSkin}/100

Definition:
- Apply a fixed, absolute smoothing filter.
- This is NOT adaptive or auto-balanced.
- Texture must remain visible.
- No glow, no whitening, no tone change.

IF intensity = 0:
- Do NOT modify skin at all.

---

4. BLEMISH REMOVAL
Intensity: ${beautySettings.removeBlemishes ? "100" : "0"}

Rules:
- Remove only temporary blemishes (acne, small pimples).
- KEEP moles, scars, birthmarks, wrinkles.

---

5. LIP COLOR
Color: ${beautySettings.lipstickColor}
Intensity: ${beautySettings.lipstickIntensity}/100

Rules:
- Apply color ONLY to lip area.
- No gloss, no shine, no reshaping.
- Natural matte finish.

IF intensity = 0:
- Do NOT modify lips.

---

6. BLUSH
Color: ${beautySettings.blushColor}
Intensity: ${beautySettings.blushIntensity}/100

Rules:
- Very subtle, symmetric.
- No contour blending.
- Must remain suitable for official ID photos.

IF intensity = 0:
- Do NOT apply blush.

---

7. CONTOUR
Intensity: ${beautySettings.contourIntensity}/100

Rules:
- Light shadow definition only.
- Do NOT reshape face.
- No slimming or lifting effects.

IF intensity = 0:
- Do NOT apply contour.

---

8. EYEBROWS
Intensity: ${beautySettings.eyebrowIntensity}/100

Rules:
- Slight definition only.
- Do NOT change eyebrow shape.

IF intensity = 0:
- Do NOT modify eyebrows.

---

9. HAIR ADJUSTMENT
Volume Intensity: ${beautySettings.hairVolume}/100
Color: ${beautySettings.hairColor || "ORIGINAL"}

Rules:
- Only tidy and slightly densify existing hair.
- Do NOT add new hair.
- No hairstyle change.

IF intensity = 0:
- Do NOT modify hair.

---

FINAL OUTPUT REQUIREMENTS:
- Output ONLY the processed image.
- Format: PNG
- Quality: High
- Encoding: Base64
- No text, no explanation, no metadata.`
  ].join("\n");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', 
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: systemInstructions }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          // Return as PNG to match requirements
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }
    throw new Error("AI không trả về dữ liệu ảnh.");

  } catch (error: any) {
    console.error("Gemini processing error:", error);
    const errorString = JSON.stringify(error);
    if (errorString.includes('429')) {
      throw new Error("AI_QUOTA_EXCEEDED");
    }
    if (errorString.includes('404') || errorString.includes('Requested entity was not found')) {
      throw new Error("MODEL_NOT_FOUND");
    }
    throw error;
  }
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

// Sub-components
import EditorBackgroundTab from './EditorBackgroundTab';
import EditorClothingTab from './EditorClothingTab';
import EditorMakeupTab from './EditorMakeupTab';
import EditorFilterTab from './EditorFilterTab';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing' | 'makeup';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings,
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const getAiSettingsHash = useCallback((s: PhotoSettings) => {
    const beauty = s.beauty;
    return JSON.stringify({
       background: s.background,
       cloth: s.clothingPrompt,
       blemish: beauty.removeBlemishes,
       smooth: beauty.smoothSkin,
       lipCol: beauty.lipstickColor,
       lipInt: beauty.lipstickIntensity,
       blushCol: beauty.blushColor,
       blushInt: beauty.blushIntensity,
       brow: beauty.eyebrowIntensity,
       contour: beauty.contourIntensity,
       hair: beauty.hairVolume,
       hairStyle: beauty.hairStyle,
       hairColor: beauty.hairColor 
    });
  }, []);

  const getRawStateHash = useCallback(() => {
     return JSON.stringify({
       background: BackgroundType.ORIGINAL,
       cloth: undefined,
       blemish: false,
       smooth: 0,
       lipCol: settings.beauty.lipstickColor,
       lipInt: 0,
       blushCol: settings.beauty.blushColor,
       blushInt: 0,
       brow: 0,
       contour: 0,
       hair: 0,
       hairStyle: 'original',
       hairColor: 'original'
     });
  }, [settings.beauty.lipstickColor, settings.beauty.blushColor]);

  const [appliedHash, setAppliedHash] = useState<string>(getRawStateHash());

  const hasPendingAiChanges = useMemo(() => {
    const currentHash = getAiSettingsHash(settings);
    const safeAppliedHash = appliedHash || getRawStateHash();
    return currentHash !== safeAppliedHash;
  }, [settings, appliedHash, getAiSettingsHash, getRawStateHash]);

  const handleApplyAiChanges = useCallback(async () => {
    const currentHash = getAiSettingsHash(settings);
    setIsProcessing(true);
    setLoadingAction("Đang xử lý...");

    try {
      const isDefault = 
        settings.background === BackgroundType.ORIGINAL && 
        !settings.clothingPrompt && 
        !settings.beauty.removeBlemishes && 
        settings.beauty.smoothSkin === 0 &&
        settings.beauty.lipstickIntensity === 0 && 
        settings.beauty.blushIntensity === 0 &&
        settings.beauty.eyebrowIntensity === 0 &&
        settings.beauty.contourIntensity === 0 &&
        settings.beauty.hairVolume === 0 &&
        (settings.beauty.hairStyle === 'original' || !settings.beauty.hairStyle) &&
        (settings.beauty.hairColor === 'original' || !settings.beauty.hairColor || settings.beauty.hairColor === 'Màu gốc');

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(
            originalImage, 
            settings.background, 
            settings.clothingPrompt, 
            settings.beauty, 
            settings.size
        );
        setProcessedUrl(result);
      }
      setAppliedHash(currentHash);
    } catch (err: any) {
      console.error(err);
      if (err.message === 'MODEL_NOT_FOUND' || (err.message && err.message.includes('entity was not found'))) {
        alert("Lỗi kết nối AI (404). Vui lòng chọn lại API Key hợp lệ.");
        if ((window as any).aistudio?.openSelectKey) {
            await (window as any).aistudio.openSelectKey();
        }
      } else if (err.message === 'AI_QUOTA_EXCEEDED') {
        alert("Giới hạn lượt dùng AI đã hết. Vui lòng thử lại sau.");
      } else {
        alert("Lỗi xử lý ảnh: " + (err.message || "Không xác định"));
      }
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  }, [settings, originalImage, getAiSettingsHash]);

  // Handlers passed to sub-components
  const handleBgChange = (bg: BackgroundType) => onUpdateSettings({ ...settings, background: bg });
  const handleClothingClick = (prompt: string) => onUpdateSettings({ ...settings, clothingPrompt: prompt });
  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });

  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);
    let sepia = 0, hue = 0, saturate = 100;
    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) { sepia = skinToneIntensity * 0.3; saturate = 100 - (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.ROSY) { sepia = skinToneIntensity * 0.15; hue = -10; saturate = 100 + (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.FAIR) { saturate = 100 - (skinToneIntensity * 0.1); }
    }
    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  const handleFinish = () => {
    const finishExport = (imgSrc: string) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.src = imgSrc;
        img.onload = () => {
            canvas.width = img.width; canvas.height = img.height;
            if (ctx) { ctx.filter = imageFilters; ctx.drawImage(img, 0, 0, canvas.width, canvas.height); onProcessedImage(canvas.toDataURL('image/png', 1.0)); onNext(); }
        };
    };
    if (hasPendingAiChanges) {
        if (confirm("Có thay đổi chưa áp dụng. Áp dụng ngay?")) {
            handleApplyAiChanges().then(() => finishExport(processedUrl));
        } else { finishExport(processedUrl); }
    } else { finishExport(processedUrl); }
  };

  return (
    <div className="flex flex-col md:flex-row h-screen h-[100dvh] w-full bg-slate-100 overflow-hidden font-sans"
       onMouseUp={() => { isDraggingRef.current = false; }}
       onTouchEnd={() => { isDraggingRef.current = false; }}
    >
      <div className="w-full md:w-[400px] bg-white shadow-2xl z-20 flex flex-col h-[50dvh] md:h-full border-r border-gray-200">
        <div className="p-3 md:p-4 border-b border-gray-100 flex justify-between items-center shrink-0">
          <h2 className="text-lg md:text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600">⚡</span> Chỉnh sửa
          </h2>
          <span className="text-[9px] md:text-[10px] font-bold text-purple-600 bg-purple-50 px-2 py-0.5 rounded-full">ID Photo Booth Pro</span>
        </div>

        <div className="px-3 pt-3 pb-1 md:px-4 md:pt-4 shrink-0">
          <div className="flex bg-gray-100 p-1 rounded-xl overflow-x-auto scrollbar-hide">
            {[
              {id: 'background', label: '1. Nền'},
              {id: 'clothing', label: '2. Áo'},
              {id: 'makeup', label: '3. Makeup'},
              {id: 'beauty', label: '4. Bộ lọc'}
            ].map((tab) => (
               <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 min-w-[65px] py-2 text-[10px] font-bold uppercase rounded-lg transition-all whitespace-nowrap ${activeTab === tab.id ? 'bg-white text-brand-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>{tab.label}</button>
            ))}
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-5 bg-white scrollbar-hide">
          {activeTab === 'background' && (
            <EditorBackgroundTab config={config} settings={settings} onBgChange={handleBgChange} />
          )}

          {activeTab === 'clothing' && (
            <EditorClothingTab config={config} settings={settings} onClothingClick={handleClothingClick} />
          )}

          {activeTab === 'makeup' && (
            <EditorMakeupTab config={config} settings={settings} onAiBeautyChange={handleAiBeautyChange} />
          )}

          {activeTab === 'beauty' && (
            <EditorFilterTab settings={settings} onClientBeautyChange={handleClientBeautyChange} />
          )}
        </div>

        <div className="p-3 md:p-4 border-t border-gray-200 bg-white space-y-2 shrink-0">
          {hasPendingAiChanges && (
            <button onClick={handleApplyAiChanges} disabled={isProcessing} className="w-full py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-xs shadow-md active:scale-95 disabled:opacity-50">✨ Áp dụng AI</button>
          )}
          <button onClick={handleFinish} disabled={isProcessing} className="w-full py-3 bg-brand-600 text-white rounded-xl font-bold text-sm shadow-lg active:scale-95 disabled:bg-gray-400">Hoàn tất & In</button>
          <button onClick={onRetake} disabled={isProcessing} className="w-full py-2 bg-slate-50 text-slate-500 rounded-xl font-bold text-xs border border-slate-200">Chụp lại</button>
        </div>
      </div>

      <div className="flex-1 bg-slate-200 relative flex items-center justify-center p-4 md:p-8 h-[50dvh] md:h-full">
        {isProcessing && (
          <div className="absolute inset-0 z-30 bg-black/30 backdrop-blur-sm flex items-center justify-center">
            <div className="bg-white p-5 rounded-2xl shadow-2xl flex flex-col items-center">
              <div className="w-8 h-8 border-3 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-3"></div>
              <p className="text-brand-800 font-bold text-xs">{loadingAction}</p>
            </div>
          </div>
        )}
        <div ref={imageContainerRef} className="relative shadow-2xl rounded-sm border-2 border-white bg-white overflow-hidden max-h-full max-w-full cursor-col-resize"
             style={{ aspectRatio: settings.size === PhotoSize.SIZE_5X5 ? '1/1' : '2/3', height: '90%' }}
             onMouseDown={() => { isDraggingRef.current = true; }}
             onTouchStart={() => { isDraggingRef.current = true; }}
             onMouseMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
             onTouchMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.touches[0].clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
        >
          <img src={originalImage} className="absolute inset-0 w-full h-full object-contain pointer-events-none" />
          <div className="absolute inset-0 w-full h-full pointer-events-none" style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}>
             <img src={processedUrl} className="absolute inset-0 w-full h-full object-contain" style={{ filter: imageFilters }} />
          </div>
          <div className="absolute top-0 bottom-0 w-0.5 bg-white z-20 shadow-md" style={{ left: `${sliderPosition}%` }}>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-6 h-6 bg-white rounded-full shadow-lg flex items-center justify-center border border-gray-200 cursor-grab active:cursor-grabbing">
              <div className="w-1 h-3 bg-brand-500 rounded-full"></div>
            </div>
          </div>

          <div className="absolute bottom-2 left-2 text-[8px] font-bold text-white bg-black/40 px-2 py-0.5 rounded uppercase tracking-widest backdrop-blur-sm pointer-events-none">Ảnh Gốc</div>
          <div className="absolute bottom-2 right-2 text-[8px] font-bold text-white bg-brand-600/60 px-2 py-0.5 rounded uppercase tracking-widest backdrop-blur-sm pointer-events-none">Đã xử lý</div>
        </div>
      </div>
    </div>
  );
};

