import { GoogleGenAI, Type } from "@google/genai";
import { BackgroundType, BeautySettings, PhotoSize } from "../types";

// Schema cho phản hồi phân tích camera AI
const analysisSchema = {
  type: Type.OBJECT,
  properties: {
    isCompliant: { type: Type.BOOLEAN },
    status: { type: Type.STRING, enum: ['VALID', 'ADJUSTING', 'INVALID'] },
    feedback: { type: Type.STRING },
    instruction: { type: Type.STRING },
    faceDetected: { type: Type.BOOLEAN }
  },
  required: ['isCompliant', 'status', 'feedback', 'instruction', 'faceDetected']
};

/**
 * Phân tích frame webcam để kiểm tra độ tuân thủ ảnh thẻ bằng Gemini 3 Flash.
 */
export const analyzeIDPhotoFrame = async (base64Frame: string): Promise<{
  isCompliant: boolean;
  status: 'VALID' | 'ADJUSTING' | 'INVALID';
  feedback: string;
  instruction: string;
  faceDetected: boolean;
}> => {
  // Always create a new instance inside the function to use the latest API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (!process.env.API_KEY) return { isCompliant: true, status: 'VALID', feedback: 'API Key Missing', instruction: 'Ready', faceDetected: true };

  const cleanBase64 = base64Frame.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } },
          { text: `Phân tích ảnh thẻ sinh trắc học. Trả về JSON.
            Tiêu chí: Mặt nhìn thẳng, mắt mở, miệng đóng, đủ sáng, không bóng đổ mạnh.
            JSON: {isCompliant: boolean, status: 'VALID'|'ADJUSTING'|'INVALID', feedback: string, instruction: string, faceDetected: boolean}.
            'instruction': Câu lệnh tiếng Việt ngắn gọn (VD: "Nâng cằm lên", "Nhìn thẳng camera").` 
          }
        ]
      },
      config: {
        responseMimeType: 'application/json',
        responseSchema: analysisSchema
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");

    return JSON.parse(text);

  } catch (error: any) {
    console.error("AI Analysis Error", error);
    return { 
      isCompliant: true, 
      status: 'VALID', 
      feedback: 'Offline Mode', 
      instruction: 'Sẵn sàng', 
      faceDetected: true 
    };
  }
};

/**
 * Xử lý ảnh thẻ bằng AI với các tham số kỹ thuật (Intensity Factors).
 * BẮT BUỘC GIỮ NGUYÊN ĐẶC ĐIỂM SINH TRẮC HỌC.
 */
export const processIDPhoto = async (
  imageBase64: string, 
  bgType: BackgroundType, 
  clothingPrompt: string | undefined,
  beautySettings: BeautySettings, 
  size: PhotoSize
): Promise<string> => {
  // Always create a new instance inside the function to use the latest API key
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  if (!process.env.API_KEY) {
    throw new Error("API Key chưa được cấu hình.");
  }

  const cleanBase64 = imageBase64.replace(/^data:image\/(png|jpeg|jpg);base64,/, "");

  // Scaled Intensity values for Safety
  const contourSafe = Math.round((beautySettings.contourIntensity / 100) * 30);
  const blemishSafe = Math.round((beautySettings.blemishIntensity / 100) * 30);
  const eyebrowSafe = Math.round((beautySettings.eyebrowIntensity / 100) * 30);
  const eyelashSafe = Math.round((beautySettings.eyelashIntensity / 100) * 25);

  // Xây dựng prompt có cấu trúc Deterministic (Nếu Intensity = 0 thì bỏ qua)
  const systemInstructions = [
    "Bạn là chuyên gia chỉnh sửa ảnh thẻ chuyên nghiệp. Thực hiện các thay đổi dựa trên các tham số cường độ (Intensity) từ 0-100.",
    "",
    "### QUY TẮC SINH TRẮC HỌC TUYỆT ĐỐI:",
    "- CẤM THAY ĐỔI cấu trúc xương mặt, hốc mắt, hình dáng mũi và cằm.",
    "- CẤM XÓA nốt ruồi, sẹo, hoặc các đặc điểm định danh vĩnh viễn.",
    "- Duy trì tính nhất quán về ánh sáng giữa khuôn mặt và phông nền mới.",
    "",
    `IMAGE EDITING INSTRUCTIONS (DETERMINISTIC):

1. BACKGROUND REPLACEMENT – STRICT TECHNICAL MODE
Mode: ${bgType}

GOAL: Replace the background with a perfectly flat, uniform color.
ABSOLUTE RULES:
- Do NOT add shadows, gradients, lighting effects, or depth.
- Do NOT simulate studio lighting or light falloff.
- The output background must be perfectly flat and uniform.

BACKGROUND COLOR RULES:
IF bgType = WHITE:
- Set background color to EXACT RGB(255, 255, 255) / HEX #FFFFFF
- Uniform fill across entire background area.
- Zero brightness variation (0% tolerance).

IF bgType = BLUE:
- Set background color to EXACT RGB(39, 146, 255) / HEX #2792FF
- Flat color only. No tonal shift.

IF bgType = GRAY:
- Set background color to EXACT RGB(209, 213, 219) / HEX #D1D5DB
- Uniform gray without noise or texture.

IF bgType = NONE:
- Do NOT modify background.

EDGE & MASKING RULES:
- Foreground (person) must be cleanly separated from background.
- Do NOT apply feathering that causes color bleeding.
- Hair edges must remain natural but background color must remain solid.
- No halo, no gray edge, no dark rim.

FORBIDDEN EFFECTS:
- Drop shadow
- Ambient shadow
- Gradient background
- Vignette
- Soft spotlight
- Background blur

---

2. CLOTHING REPLACEMENT
Intensity: ${clothingPrompt ? "100" : "0"}

IF enabled:
- Replace clothing with: "${clothingPrompt}"
- Clothing must look neutral, formal, and suitable for ID photos.
- Collar must be natural and realistic.
- Do NOT change body shape or posture.

IF disabled:
- Do NOT alter clothing.

---

3. SKIN SMOOTHING
Intensity: ${beautySettings.smoothSkin}/100

Definition:
- Apply a fixed, absolute smoothing filter.
- This is NOT adaptive or auto-balanced.
- Texture must remain visible.
- No glow, no whitening, no tone change.

IF intensity = 0:
- Do NOT modify skin at all.

---

4. BLEMISH CLEANING (INTENSITY MODE)
Intensity: ${blemishSafe}/100

STRICT RULES:
- Remove only temporary skin imperfections (acne, small pimples).
- Do NOT remove moles, scars, freckles, birthmarks, or wrinkles.
- Do NOT blur or smooth surrounding skin excessively.
- Skin texture must remain visible and natural.
- No whitening, no tone correction.

INTENSITY DEFINITION:
- 0–10: Minimal correction
- 11–20: Moderate cleanup
- 21–30: Maximum allowed without skin flattening

IF intensity = 0:
- Do NOT remove blemishes.

---

5. LIP COLOR
Color: ${beautySettings.lipstickColor}
Intensity: ${beautySettings.lipstickIntensity}/100

Rules:
- Apply color ONLY to lip area.
- No gloss, no shine, no reshaping.
- Natural matte finish.

IF intensity = 0:
- Do NOT modify lips.

---

6. BLUSH
Color: ${beautySettings.blushColor}
Intensity: ${beautySettings.blushIntensity}/100

Rules:
- Very subtle, symmetric.
- No contour blending.
- Must remain suitable for official ID photos.

IF intensity = 0:
- Do NOT apply blush.

---

7. CONTOUR (MAKEUP MODE)
Intensity: ${contourSafe}/100

STRICT RULES:
- This is a LIGHT SHADING operation only.
- Do NOT change face shape, jawline, cheekbone position, or nose size.
- Apply subtle shadow along existing facial contours only.
- No slimming, lifting, or sculpting effects.
- No color shift; use natural skin-adjacent tones only.
- No gradient exaggeration.

INTENSITY DEFINITION:
- 0–10: Almost invisible
- 11–20: Very subtle
- 21–30: Soft definition (maximum allowed for ID photos)

IF intensity = 0:
- Do NOT apply contour in any form.

---

8. HAIR ADJUSTMENT
Volume Intensity: ${beautySettings.hairVolume}/100
Color: ${beautySettings.hairColor || "ORIGINAL"}

Rules:
- Only tidy and slightly densify existing hair.
- Do NOT add new hair.
- No hairstyle change.

IF intensity = 0:
- Do NOT modify hair.

---

9. EYEBROW DRAWING (MAKEUP MODE)
Mode: Makeup
Intensity: ${eyebrowSafe}/100

STRICT RULES:
- This is a DRAWING / DEFINITION operation, NOT reshaping.
- Do NOT change eyebrow position, length, thickness, or arch.
- Follow the EXISTING eyebrow shape exactly.
- Use hair-like strokes, natural density.
- Color must match original eyebrow color.
- No sharp edges, no over-darkening.

IF intensity = 0:
- Do NOT draw or enhance eyebrows in any way.

---

10. EYELASH DRAWING (MAKEUP MODE)
Mode: Makeup
Intensity: ${eyelashSafe}/100

STRICT RULES:
- Enhance ONLY existing eyelashes.
- Do NOT add dramatic, long, curled, or artificial lashes.
- No mascara clumping, no eyeliner, no eye shadow.
- Upper lashes only unless lower lashes are clearly visible.
- Must remain suitable for official ID photos.

IF intensity = 0:
- Do NOT modify eyelashes.

---

GLOBAL MAKEUP SAFETY CONSTRAINTS:
- All makeup effects must be acceptable for official documents.
- No glam, beauty portrait, or social media styling.
- No identity-altering changes.
- No adaptive AI beautification.
- Makeup effects must be subtle, neutral, and ID-photo compliant.
- Do NOT reshape face, skin texture, or identity features.
- Do NOT auto-adjust intensity.
- Use absolute, fixed-strength filters only.
- If intensity = 0, the operation must be fully skipped.

---

FINAL OUTPUT REQUIREMENTS:
- Output ONLY the processed image.
- Format: PNG
- Quality: High
- Encoding: Base64
- No text, no explanation, no metadata.`
  ].join("\n");

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', 
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/png', data: cleanBase64 } },
          { text: systemInstructions }
        ]
      }
    });

    const parts = response.candidates?.[0]?.content?.parts;
    if (parts) {
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          // Return as PNG to match requirements
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }
    throw new Error("AI không trả về dữ liệu ảnh.");

  } catch (error: any) {
    console.error("Gemini processing error:", error);
    const errorString = JSON.stringify(error);
    if (errorString.includes('429')) {
      throw new Error("AI_QUOTA_EXCEEDED");
    }
    if (errorString.includes('404') || errorString.includes('Requested entity was not found')) {
      throw new Error("MODEL_NOT_FOUND");
    }
    throw error;
  }
};

