  // --- VIEWER MODE (QR SCAN) ---
  if (viewerPhotoId) {
    return <PhotoViewer photoId={viewerPhotoId} config={config} />;
  }

  // --- ADMIN MODE ---
  if (isAdminMode) {
    return (
      <AdminDashboard 
