           onClick={onAutoCaptureToggle}
           className={`
              w-12 h-12 md:w-14 md:h-14 rounded-2xl flex items-center justify-center transition-all duration-300 border-2 active:scale-95
              ${isAutoCaptureEnabled 
                ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg shadow-indigo-500/40 ring-2 ring-indigo-500/20' 
                : 'bg-black/50 border-gray-600 text-gray-400 hover:border-gray-400'}
           `}
           title={isAutoCaptureEnabled ? "Tắt chụp tự động" : "Bật chụp tự động (AI Auto)"}
         >
            <svg className={`w-6 h-6 md:w-7 md:h-7 ${isAutoCaptureEnabled ? 'animate-pulse' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z"></path></svg>
         </button>
         <span className={`text-[9px] font-black uppercase tracking-tighter ${isAutoCaptureEnabled ? 'text-indigo-400' : 'text-gray-500'}`}>
            {isAutoCaptureEnabled ? 'Auto ON' : 'Auto OFF'}
         </span>
      </div>

      <div className="flex flex-col items-center gap-3">
          <div className={`text-xs md:text-sm font-bold px-4 py-1.5 rounded-full shadow-lg backdrop-blur transition-colors ${validationStatus === 'valid' ? 'bg-green-500 text-white' : 'bg-gray-800/80 text-gray-400'}`}>
            {validationStatus === 'valid' ? '✔CHẤP NHẬN' : '⚠️ Đang xử lý'}
          </div>

          <button
            onClick={onCaptureClick}
            disabled={countdown !== null || isCapturing}
            className={`
              w-20 h-20 md:w-24 md:h-24 rounded-full border-4 transition-all duration-300 flex items-center justify-center shadow-2xl relative
              ${validationStatus === 'valid' 
                ? 'bg-white border-green-500 hover:border-green-400 hover:scale-105 active:scale-95 cursor-pointer ring-4 ring-green-500/30' 
                : 'bg-gray-700 border-gray-600 opacity-90 cursor-pointer'} 
            `}
          >
            <div className={`w-16 h-16 md:w-20 md:h-20 rounded-full transition-all duration-300 flex items-center justify-center ${validationStatus === 'valid' ? 'bg-green-600' : 'bg-gray-600'}`}>
                {validationStatus !== 'valid' && (
                  <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 9a2 2 0 012-2h.93a2 2 0 001.664-.89l.812-1.22A2 2 0 0110.07 4h3.86a2 2 0 011.664.89l.812 1.22A2 2 0 0018.07 7H19a2 2 0 012 2v9a2 2 0 01-2 2H5a2 2 0 01-2-2V9z"></path><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 13a3 3 0 11-6 0 3 3 0 016 0z"></path></svg>
                )}
            </div>
          </button>
      </div>
      <div className="w-12 md:w-14"></div>
    </div>
  );
};

export default CaptureControls;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { BackgroundType, PhotoSettings, PhotoSize, AppConfig, SkinToneType } from '../types';
import { processIDPhoto } from '../services/geminiService';

// Sub-components
import EditorBackgroundTab from './EditorBackgroundTab';
import EditorClothingTab from './EditorClothingTab';
import EditorMakeupTab from './EditorMakeupTab';
import EditorFilterTab from './EditorFilterTab';

interface ImageEditorProps {
  originalImage: string;
  settings: PhotoSettings;
  onUpdateSettings: (newSettings: PhotoSettings) => void;
  onProcessedImage: (img: string) => void;
  onNext: () => void;
  onRetake: () => void;
  config: AppConfig;
}

type EditorTab = 'background' | 'beauty' | 'clothing' | 'makeup';

const ImageEditor: React.FC<ImageEditorProps> = ({ 
  originalImage, 
  settings, 
  onUpdateSettings, 
  onProcessedImage,
  onNext,
  onRetake,
  config
}) => {
  const [processedUrl, setProcessedUrl] = useState<string>(originalImage);
  const [isProcessing, setIsProcessing] = useState(false);
  const [activeTab, setActiveTab] = useState<EditorTab>('background');
  const [loadingAction, setLoadingAction] = useState<string>('');

  const [sliderPosition, setSliderPosition] = useState(50);
  const imageContainerRef = useRef<HTMLDivElement>(null);
  const isDraggingRef = useRef(false);

  const getAiSettingsHash = useCallback((s: PhotoSettings) => {
    const beauty = s.beauty;
    return JSON.stringify({
       background: s.background,
       cloth: s.clothingPrompt,
       blemish: beauty.blemishIntensity,
       smooth: beauty.smoothSkin,
       lipCol: beauty.lipstickColor,
       lipInt: beauty.lipstickIntensity,
       blushCol: beauty.blushColor,
       blushInt: beauty.blushIntensity,
       brow: beauty.eyebrowIntensity,
       lash: beauty.eyelashIntensity,
       contour: beauty.contourIntensity,
       hair: beauty.hairVolume,
       hairStyle: beauty.hairStyle,
       hairColor: beauty.hairColor 
    });
  }, []);

  const getRawStateHash = useCallback(() => {
     return JSON.stringify({
       background: BackgroundType.ORIGINAL,
       cloth: undefined,
       blemish: 0,
       smooth: 0,
       lipCol: settings.beauty.lipstickColor,
       lipInt: 0,
       blushCol: settings.beauty.blushColor,
       blushInt: 0,
       brow: 0,
       lash: 0,
       contour: 0,
       hair: 0,
       hairStyle: 'original',
       hairColor: 'original'
     });
  }, [settings.beauty.lipstickColor, settings.beauty.blushColor]);

  const [appliedHash, setAppliedHash] = useState<string>(getRawStateHash());

  const hasPendingAiChanges = useMemo(() => {
    const currentHash = getAiSettingsHash(settings);
    const safeAppliedHash = appliedHash || getRawStateHash();
    return currentHash !== safeAppliedHash;
  }, [settings, appliedHash, getAiSettingsHash, getRawStateHash]);

  const handleApplyAiChanges = useCallback(async () => {
    const currentHash = getAiSettingsHash(settings);
    setIsProcessing(true);
    setLoadingAction("Đang xử lý...");

    try {
      const isDefault = 
        settings.background === BackgroundType.ORIGINAL && 
        !settings.clothingPrompt && 
        settings.beauty.blemishIntensity === 0 && 
        settings.beauty.smoothSkin === 0 &&
        settings.beauty.lipstickIntensity === 0 && 
        settings.beauty.blushIntensity === 0 &&
        settings.beauty.eyebrowIntensity === 0 &&
        settings.beauty.eyelashIntensity === 0 &&
        settings.beauty.contourIntensity === 0 &&
        settings.beauty.hairVolume === 0 &&
        (settings.beauty.hairStyle === 'original' || !settings.beauty.hairStyle) &&
        (settings.beauty.hairColor === 'original' || !settings.beauty.hairColor || settings.beauty.hairColor === 'Màu gốc');

      if (isDefault) {
        setProcessedUrl(originalImage);
      } else {
        const result = await processIDPhoto(
            originalImage, 
            settings.background, 
            settings.clothingPrompt, 
            settings.beauty, 
            settings.size
        );
        setProcessedUrl(result);
      }
      setAppliedHash(currentHash);
    } catch (err: any) {
      console.error(err);
      if (err.message === 'MODEL_NOT_FOUND' || (err.message && err.message.includes('entity was not found'))) {
        alert("Lỗi kết nối AI (404). Vui lòng chọn lại API Key hợp lệ.");
        if ((window as any).aistudio?.openSelectKey) {
            await (window as any).aistudio.openSelectKey();
        }
      } else if (err.message === 'AI_QUOTA_EXCEEDED') {
        alert("Giới hạn lượt dùng AI đã hết. Vui lòng thử lại sau.");
      } else {
        alert("Lỗi xử lý ảnh: " + (err.message || "Không xác định"));
      }
    } finally {
      setIsProcessing(false);
      setLoadingAction('');
    }
  }, [settings, originalImage, getAiSettingsHash]);

  // Handlers passed to sub-components
  const handleBgChange = (bg: BackgroundType) => onUpdateSettings({ ...settings, background: bg });
  const handleClothingClick = (prompt: string) => onUpdateSettings({ ...settings, clothingPrompt: prompt });
  const handleAiBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });
  const handleClientBeautyChange = (key: keyof typeof settings.beauty, value: any) => onUpdateSettings({ ...settings, beauty: { ...settings.beauty, [key]: value } });

  const imageFilters = useMemo(() => {
    const { lighting, contrast, skinToneIntensity, skinToneType } = settings.beauty;
    const brightnessVal = 100 + (lighting * 1.5); 
    const contrastVal = 100 + (contrast * 1.5);
    let sepia = 0, hue = 0, saturate = 100;
    if (skinToneIntensity > 0) {
        if (skinToneType === SkinToneType.TAN) { sepia = skinToneIntensity * 0.3; saturate = 100 - (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.ROSY) { sepia = skinToneIntensity * 0.15; hue = -10; saturate = 100 + (skinToneIntensity * 0.1); }
        else if (skinToneType === SkinToneType.FAIR) { saturate = 100 - (skinToneIntensity * 0.1); }
    }
    return `brightness(${brightnessVal}%) contrast(${contrastVal}%) saturate(${saturate}%) sepia(${sepia}%) hue-rotate(${hue}deg)`;
  }, [settings.beauty]);

  const handleFinish = () => {
    const finishExport = (imgSrc: string) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const img = new Image();
        img.crossOrigin = "anonymous";
        img.src = imgSrc;
        img.onload = () => {
            canvas.width = img.width; canvas.height = img.height;
            if (ctx) { ctx.filter = imageFilters; ctx.drawImage(img, 0, 0, canvas.width, canvas.height); onProcessedImage(canvas.toDataURL('image/png', 1.0)); onNext(); }
        };
    };
    if (hasPendingAiChanges) {
        if (confirm("Có thay đổi chưa áp dụng. Áp dụng ngay?")) {
            handleApplyAiChanges().then(() => finishExport(processedUrl));
        } else { finishExport(processedUrl); }
    } else { finishExport(processedUrl); }
  };

  return (
    <div className="flex flex-col-reverse md:flex-row h-[100dvh] w-full bg-slate-100 overflow-hidden font-sans pb-safe"
       onMouseUp={() => { isDraggingRef.current = false; }}
       onTouchEnd={() => { isDraggingRef.current = false; }}
    >
      {/* CONTROLS SIDEBAR / BOTTOM SHEET */}
      <div className="w-full md:w-[400px] bg-white shadow-2xl z-20 flex flex-col h-[50dvh] md:h-full border-t md:border-t-0 md:border-r border-gray-200 shrink-0">

        {/* Header - Hidden on mobile to save space, visible on desktop */}
        <div className="hidden md:flex p-3 md:p-4 border-b border-gray-100 justify-between items-center shrink-0">
          <h2 className="text-lg md:text-xl font-extrabold text-gray-800 flex items-center gap-2">
            <span className="text-brand-600">⚡</span> Chỉnh sửa
          </h2>
          <span className="text-[9px] md:text-[10px] font-bold text-purple-600 bg-purple-50 px-2 py-0.5 rounded-full">ID Photo Booth Pro</span>
        </div>

        {/* Tab Navigation */}
        <div className="px-2 pt-2 pb-1 md:px-4 md:pt-4 shrink-0 border-b border-gray-100 md:border-none">
          <div className="flex bg-gray-100 p-1 rounded-xl overflow-x-auto scrollbar-hide gap-1">
            {[
              {id: 'background', label: '1. Nền'},
              {id: 'clothing', label: '2. Áo'},
              {id: 'makeup', label: '3. Makeup'},
              {id: 'beauty', label: '4. Bộ lọc'}
            ].map((tab) => (
               <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 min-w-[75px] py-2.5 text-xs font-bold uppercase rounded-lg transition-all whitespace-nowrap active:scale-95 ${activeTab === tab.id ? 'bg-white text-brand-600 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}>{tab.label}</button>
            ))}
          </div>
        </div>

        {/* Scrollable Controls Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-5 bg-white scrollbar-hide">
          {activeTab === 'background' && (
            <EditorBackgroundTab config={config} settings={settings} onBgChange={handleBgChange} />
          )}

          {activeTab === 'clothing' && (
            <EditorClothingTab config={config} settings={settings} onClothingClick={handleClothingClick} />
          )}

          {activeTab === 'makeup' && (
            <EditorMakeupTab config={config} settings={settings} onAiBeautyChange={handleAiBeautyChange} />
          )}

          {activeTab === 'beauty' && (
            <EditorFilterTab settings={settings} onClientBeautyChange={handleClientBeautyChange} />
          )}
        </div>

        {/* Actions Footer */}
        <div className="p-3 md:p-4 border-t border-gray-200 bg-white space-y-2 shrink-0">
          {hasPendingAiChanges && (
            <button onClick={handleApplyAiChanges} disabled={isProcessing} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-md active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2">
               {isProcessing ? <div className="w-5 h-5 border-2 border-white/50 border-t-white rounded-full animate-spin"></div> : "✨"} 
               Áp dụng AI
            </button>
          )}
          <div className="flex gap-3">
            <button onClick={onRetake} disabled={isProcessing} className="flex-1 py-3 bg-slate-50 text-slate-600 hover:bg-slate-100 rounded-xl font-bold text-sm border border-slate-200 active:scale-95">Chụp lại</button>
            <button onClick={handleFinish} disabled={isProcessing} className="flex-[2] py-3 bg-brand-600 text-white rounded-xl font-bold text-sm shadow-lg active:scale-95 disabled:bg-gray-400">Hoàn tất & In</button>
          </div>
        </div>
      </div>

      {/* IMAGE PREVIEW AREA */}
      <div className="flex-1 bg-slate-200 relative flex items-center justify-center p-4 md:p-8 h-[50dvh] md:h-full shrink-0">
        {isProcessing && (
          <div className="absolute inset-0 z-30 bg-black/30 backdrop-blur-sm flex items-center justify-center">
            <div className="bg-white p-5 rounded-2xl shadow-2xl flex flex-col items-center">
              <div className="w-8 h-8 border-3 border-brand-200 border-t-brand-600 rounded-full animate-spin mb-3"></div>
              <p className="text-brand-800 font-bold text-xs">{loadingAction}</p>
            </div>
          </div>
        )}

        {/* Mobile Header (Only visible on mobile) */}
        <div className="absolute top-0 left-0 right-0 p-2 flex md:hidden justify-between items-center z-10 bg-gradient-to-b from-black/20 to-transparent pointer-events-none">
           <span className="text-[10px] font-bold text-white bg-black/20 px-2 py-0.5 rounded-full backdrop-blur-md">ID Photo Booth Pro</span>
        </div>

        <div ref={imageContainerRef} className="relative shadow-2xl rounded-sm border-2 border-white bg-white overflow-hidden max-h-full max-w-full cursor-col-resize touch-none"
             style={{ aspectRatio: settings.size === PhotoSize.SIZE_5X5 ? '1/1' : '2/3', height: '100%', maxHeight: '100%' }}
             onMouseDown={() => { isDraggingRef.current = true; }}
             onTouchStart={() => { isDraggingRef.current = true; }}
             onMouseMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
             onTouchMove={(e) => {
               if (isDraggingRef.current && imageContainerRef.current) {
                  const rect = imageContainerRef.current.getBoundingClientRect();
                  const x = Math.max(0, Math.min(e.touches[0].clientX - rect.left, rect.width));
                  setSliderPosition((x / rect.width) * 100);
               }
             }}
        >
          <img src={originalImage} className="absolute inset-0 w-full h-full object-contain pointer-events-none" />
          <div className="absolute inset-0 w-full h-full pointer-events-none" style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}>
             <img src={processedUrl} className="absolute inset-0 w-full h-full object-contain" style={{ filter: imageFilters }} />
          </div>
          <div className="absolute top-0 bottom-0 w-0.5 bg-white z-20 shadow-md" style={{ left: `${sliderPosition}%` }}>
            <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-8 h-8 md:w-6 md:h-6 bg-white rounded-full shadow-lg flex items-center justify-center border border-gray-200 cursor-grab active:cursor-grabbing">
              <svg className="w-4 h-4 text-brand-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 9l4-4 4 4m0 6l-4 4-4-4"></path></svg>
            </div>
          </div>

          <div className="absolute bottom-2 left-2 text-[8px] font-bold text-white bg-black/40 px-2 py-0.5 rounded uppercase tracking-widest backdrop-blur-sm pointer-events-none">Ảnh Gốc</div>
          <div className="absolute bottom-2 right-2 text-[8px] font-bold text-white bg-brand-600/60 px-2 py-0.5 rounded uppercase tracking-widest backdrop-blur-sm pointer-events-none">Đã xử lý</div>
        </div>
      </div>
    </div>
  );
};

export default ImageEditor;

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { PhotoSettings, PhotoSize, AppConfig, BackgroundType } from '../types';
import { savePhotoToCloud } from '../services/databaseService';

// Sub-components
import PrintSidebar from './PrintSidebar';
import PrintSheetView from './PrintSheetView';

interface PrintPreviewProps {
  processedImage: string;
  size: PhotoSize;
  settings: PhotoSettings;
  onBack: () => void;
  onNew: () => void;
  onSaved?: () => void;
  onHome: () => void;
  config: AppConfig;
}

const PrintPreview: React.FC<PrintPreviewProps> = ({ 
  processedImage, size, settings, onBack, onNew, onHome, config
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [realPhotoId, setRealPhotoId] = useState<string | null>(null);
  const [qrUrl, setQrUrl] = useState<string>('');
  const [sheetImages, setSheetImages] = useState<string[]>([]);

  const layout = size === PhotoSize.SIZE_3X4 ? { cols: 4, rows: 4, photoW_mm: 30, photoH_mm: 40, rotated: false, maxOnSheet: 16 }
              : size === PhotoSize.SIZE_5X5 ? { cols: 2, rows: 3, photoW_mm: 50, photoH_mm: 50, rotated: false, maxOnSheet: 6 }
              : { cols: 2, rows: 4, photoW_mm: 60, photoH_mm: 40, rotated: true, maxOnSheet: 8 };

  const totalSheets = Math.ceil(settings.printQuantity / layout.maxOnSheet);

  const loadImage = (src: string): Promise<HTMLImageElement> => new Promise((res, rej) => { const img = new Image(); img.crossOrigin="anonymous"; img.onload=()=>res(img); img.onerror=rej; img.src=src; });

  const generateSheetCanvas = async (sheetIdx: number, photoImg: HTMLImageElement, logoImg: HTMLImageElement | null, qrImg: HTMLImageElement | null): Promise<string> => {
        const DPI = 300; const MM_TO_PX = DPI / 25.4;
        const canvas = document.createElement('canvas'); canvas.width = Math.ceil(130 * MM_TO_PX); canvas.height = Math.ceil(180 * MM_TO_PX);
        const ctx = canvas.getContext('2d'); if (!ctx) throw new Error();
        ctx.fillStyle = '#ffffff'; ctx.fillRect(0, 0, canvas.width, canvas.height);
        const end = Math.min((sheetIdx + 1) * layout.maxOnSheet, settings.printQuantity);
        const count = end - (sheetIdx * layout.maxOnSheet);
        const cellW = layout.photoW_mm * MM_TO_PX; const cellH = layout.photoH_mm * MM_TO_PX;
        const startX = (canvas.width - (layout.cols * cellW)) / 2; const startY = 5 * MM_TO_PX; 
        const bgCol = settings.background === BackgroundType.ORIGINAL ? null : (config.backgroundConfig.find(b => b.type === settings.background)?.hexColor || '#ffffff');
        for (let i = 0; i < count; i++) {
            const x = startX + (i % layout.cols) * cellW; const y = startY + Math.floor(i / layout.cols) * cellH;
            ctx.save(); ctx.beginPath(); ctx.rect(x, y, cellW, cellH); ctx.clip();
            if (bgCol) { ctx.fillStyle = bgCol; ctx.fillRect(x, y, cellW, cellH); }
            if (layout.rotated) { ctx.translate(x + cellW/2, y + cellH/2); ctx.rotate(-Math.PI/2); ctx.drawImage(photoImg, -cellH/2, -cellW/2, cellH, cellW); }
            else ctx.drawImage(photoImg, x, y, cellW, cellH);
            ctx.restore(); ctx.strokeStyle = '#d1d5db'; ctx.setLineDash([15, 15]); ctx.strokeRect(x, y, cellW, cellH);
        }
        const footerY = canvas.height - 15 * MM_TO_PX; ctx.fillStyle = '#ffffff'; ctx.fillRect(0, footerY, canvas.width, 15 * MM_TO_PX);
        ctx.beginPath(); ctx.moveTo(0, footerY); ctx.lineTo(canvas.width, footerY); ctx.strokeStyle = '#000000'; ctx.lineWidth = 2; ctx.setLineDash([]); ctx.stroke();
        let lo = 5 * MM_TO_PX; if (logoImg) { const lh = 10 * MM_TO_PX; const lw = logoImg.width * (lh / logoImg.height); ctx.drawImage(logoImg, lo, footerY + 2.5 * MM_TO_PX, lw, lh); lo += lw + 3 * MM_TO_PX; }
        ctx.fillStyle = '#000000'; ctx.font = `bold ${5 * MM_TO_PX}px sans-serif`; ctx.fillText(config.shopName, lo, footerY + 7 * MM_TO_PX);
        if (qrImg) ctx.drawImage(qrImg, canvas.width - 17 * MM_TO_PX, footerY + 1.5 * MM_TO_PX, 12 * MM_TO_PX, 12 * MM_TO_PX);
        return canvas.toDataURL('image/png');
  };

  useEffect(() => {
     if (!qrUrl) return; 
     (async () => {
         try {
             const [p, l, q] = await Promise.all([loadImage(processedImage), config.logoUrl ? loadImage(config.logoUrl).catch(() => null) : null, loadImage(qrUrl).catch(() => null)]);
             const sheets = []; for (let i = 0; i < totalSheets; i++) sheets.push(await generateSheetCanvas(i, p, l, q));
             setSheetImages(sheets);
         } catch {}
     })();
  }, [qrUrl, processedImage, totalSheets, config]);

  useEffect(() => {
    (async () => {
      setIsSaving(true); const id = await savePhotoToCloud({ id: 'temp', dataUrl: processedImage, timestamp: Date.now(), settings });
      if (id) { setRealPhotoId(id); const v = `${window.location.href.split('?')[0]}?photoId=${id}`; setQrUrl(`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(v)}&ecc=H`); }
      setIsSaving(false);
    })();
  }, []); 

  const handleDownload = () => { sheetImages.forEach((d, i) => { const l = document.createElement('a'); l.href = d; l.download = `Photo-Sheet-${i+1}.png`; l.click(); }); };

  return (
    <div className="flex flex-col h-full bg-slate-100 relative min-h-[100dvh]">
      {document.getElementById('print-mount') && createPortal(<div className="print-portal-root">{sheetImages.map((s, i) => <div key={i} className="sheet-page"><img src={s} alt="" /></div>)}</div>, document.getElementById('print-mount')!)}

      <header className="bg-white shadow-sm p-4 flex justify-between items-center z-20 shrink-0 sticky top-0">
        <h1 className="text-lg md:text-xl font-extrabold text-slate-800 flex items-center gap-2">🖨️ Print Preview</h1>
        <button onClick={onBack} className="px-3 py-1.5 md:px-4 md:py-2 text-sm font-bold text-slate-600 hover:bg-slate-100 rounded-lg">Quay lại</button>
      </header>

      {/* Scrollable Container */}
      <div className="flex-1 overflow-y-auto flex flex-col md:flex-row p-4 md:p-8 gap-8 bg-slate-100 pb-safe">

        {/* Preview Area */}
        <div className="w-full flex-1 flex flex-col items-center">
             <PrintSheetView sheetImages={sheetImages} isSaving={isSaving} />
        </div>

        {/* Controls Area (Stacked at bottom on mobile) */}
        <div className="w-full md:w-80 shrink-0">
            <PrintSidebar 
                photoId={realPhotoId}
                isSaving={isSaving}
                sheetImages={sheetImages}
                qrUrl={qrUrl}
                settings={settings}
                config={config}
