import { QRLabelMapping } from "../types";

const MAPPING_STORAGE_KEY = 'id_photo_booth_qr_mappings';

// Exclude confusing characters: 0, O, 1, I, l
const CHARSET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
const CODE_LENGTH = 6;

const getMappings = (): QRLabelMapping[] => {
  try {
    const data = localStorage.getItem(MAPPING_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  } catch {
    return [];
  }
};

const saveMappings = (mappings: QRLabelMapping[]) => {
  localStorage.setItem(MAPPING_STORAGE_KEY, JSON.stringify(mappings));
};

const generateCode = (existingCodes: Set<string>): string => {
  let result = '';
  while (result.length < CODE_LENGTH || existingCodes.has(result)) {
    result = '';
    for (let i = 0; i < CODE_LENGTH; i++) {
      result += CHARSET.charAt(Math.floor(Math.random() * CHARSET.length));
    }
  }
  return result;
};

/**
 * Ensures a unique code exists for a given photo ID.
 * If mapping exists, return it. If not, create new one.
 */
export const getOrCreateQRCode = (photoId: string): QRLabelMapping => {
  const mappings = getMappings();
  const existing = mappings.find(m => m.photoId === photoId);

  if (existing) return existing;

  // Generate new
  const existingCodes = new Set(mappings.map(m => m.code));
  const newCode = generateCode(existingCodes);

  const newMapping: QRLabelMapping = {
    code: newCode,
    photoId: photoId,
    createdAt: Date.now()
  };

  mappings.push(newMapping);
  saveMappings(mappings);

  return newMapping;
};

export const resolveCodeToLink = (code: string): string | null => {
  const mappings = getMappings();
  const mapping = mappings.find(m => m.code.toUpperCase() === code.toUpperCase());

  if (!mapping) return null;

  // Reconstruct the download URL based on existing logic in App.tsx
  const baseUrl = window.location.href.split('?')[0];
  return `${baseUrl}?photoId=${mapping.photoId}`;
};

export const getQRImageUrl = (content: string): string => {
    // Using standard ECC 'L' for cleaner code at small sizes (14mm)
    return `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodeURIComponent(content)}&color=000000&bgcolor=FFFFFF&margin=0&ecc=L`;
};

import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { getPhotosFromCloud } from '../services/databaseService';
import { getOrCreateQRCode, resolveCodeToLink, getQRImageUrl } from '../services/qrCodeService';
import { SavedPhoto, QRLabelMapping } from '../types';

const AdminQRLabelTab: React.FC = () => {
  const [photos, setPhotos] = useState<SavedPhoto[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedPhotos, setSelectedPhotos] = useState<Set<string>>(new Set());
  const [mappings, setMappings] = useState<Record<string, QRLabelMapping>>({});

  // Test Section State
  const [testCode, setTestCode] = useState('');
  const [testResult, setTestResult] = useState<{link: string, valid: boolean} | null>(null);

  // Print Portal State
  const [isPrinting, setIsPrinting] = useState(false);

  useEffect(() => {
    loadPhotos();
  }, []);

  const loadPhotos = async () => {
    setLoading(true);
    const data = await getPhotosFromCloud();
    // Sort by newest
    data.sort((a, b) => b.timestamp - a.timestamp);
    setPhotos(data);
    setLoading(false);
  };

  const handleGenerateCode = (photoId: string) => {
    const mapping = getOrCreateQRCode(photoId);
    setMappings(prev => ({ ...prev, [photoId]: mapping }));
    // Auto select when generated
    const newSelected = new Set(selectedPhotos);
    newSelected.add(photoId);
    setSelectedPhotos(newSelected);
  };

  const handleTestCode = () => {
    if (!testCode) {
        setTestResult(null);
        return;
    }
    const link = resolveCodeToLink(testCode);
    setTestResult({
        link: link || '',
        valid: !!link
    });
  };

  const handlePrint = () => {
    setIsPrinting(true);
    setTimeout(() => {
        window.print();
        // Reset after print dialog likely closes
        // Note: JS cannot detect when print dialog closes, but we leave the portal open 
        // until user clicks "Back" or similar in a real app, 
        // but here we toggle purely for CSS application.
        // For better UX, we can leave isPrinting true and add a "Cancel Print Mode" button.
    }, 500);
  };

  const toggleSelection = (id: string) => {
      const newSet = new Set(selectedPhotos);
      if (newSet.has(id)) newSet.delete(id);
      else {
          newSet.add(id);
          // Ensure code exists if selected
          if (!mappings[id]) {
              const m = getOrCreateQRCode(id);
              setMappings(prev => ({ ...prev, [id]: m }));
          }
      }
      setSelectedPhotos(newSet);
  };

  return (
    <div className="space-y-6 animate-fadeIn h-full flex flex-col lg:flex-row gap-6">
      {/* Left: Photo Selection */}
      <div className="flex-1 bg-white p-6 rounded-2xl shadow-sm border border-gray-100 flex flex-col min-h-[500px]">
        <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-bold text-gray-800">Danh sách ảnh ({photos.length})</h3>
            <button onClick={loadPhotos} className="text-sm text-brand-600 font-bold hover:underline">Làm mới</button>
        </div>

        {loading ? (
             <div className="flex-1 flex items-center justify-center"><div className="animate-spin w-8 h-8 border-4 border-brand-200 border-t-brand-600 rounded-full"></div></div>
        ) : (
            <div className="flex-1 overflow-y-auto space-y-2 pr-2">
                {photos.map(p => {
                    const hasMapping = !!mappings[p.id]; // In local state, or check logic
                    // We might want to pre-load mappings for all photos, but for now we do lazy load
                    return (
                        <div 
                            key={p.id} 
                            onClick={() => toggleSelection(p.id)}
                            className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${selectedPhotos.has(p.id) ? 'border-brand-500 bg-brand-50' : 'border-slate-100 hover:bg-slate-50'}`}
                        >
                            <div className={`w-5 h-5 rounded border flex items-center justify-center ${selectedPhotos.has(p.id) ? 'bg-brand-500 border-brand-500 text-white' : 'bg-white border-gray-300'}`}>
                                {selectedPhotos.has(p.id) && "✓"}
                            </div>
                            <img src={p.dataUrl} className="w-10 h-14 object-cover rounded bg-gray-200" />
                            <div className="flex-1 min-w-0">
                                <div className="text-xs text-gray-500">{new Date(p.timestamp).toLocaleString('vi-VN')}</div>
                                <div className="text-xs font-bold truncate text-gray-700">{p.id}</div>
                            </div>
                            <div className="text-right">
                                {mappings[p.id] ? (
                                    <span className="bg-gray-800 text-white font-mono font-bold text-xs px-2 py-1 rounded tracking-wider">{mappings[p.id].code}</span>
                                ) : (
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); handleGenerateCode(p.id); }}
                                        className="text-[10px] bg-slate-200 hover:bg-slate-300 text-slate-700 px-2 py-1 rounded font-bold"
                                    >
                                        Tạo Code
                                    </button>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>
        )}
      </div>

      {/* Right: Actions & Preview */}
      <div className="w-full lg:w-80 space-y-6">
         {/* Code Tester */}
         <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="font-bold text-gray-800 mb-4 border-b pb-2">Kiểm tra Code</h3>
            <div className="flex gap-2 mb-3">
                <input 
                    type="text" 
                    value={testCode}
                    onChange={(e) => setTestCode(e.target.value.toUpperCase())}
                    placeholder="Nhập mã 6 ký tự..."
                    className="flex-1 border border-gray-300 rounded-lg px-3 py-2 text-sm font-mono uppercase focus:ring-2 focus:ring-brand-500 outline-none"
                    maxLength={8}
                />
                <button onClick={handleTestCode} className="px-4 bg-gray-100 hover:bg-gray-200 rounded-lg text-sm font-bold">Check</button>
            </div>

            {testResult && (
                <div className={`p-3 rounded-lg text-xs ${testResult.valid ? 'bg-green-50 text-green-700 border border-green-200' : 'bg-red-50 text-red-700 border border-red-200'}`}>
                    {testResult.valid ? (
                        <div>
                            <div className="font-bold mb-1">✔ Code Hợp lệ</div>
                            <a href={testResult.link} target="_blank" className="underline break-all block opacity-80">{testResult.link}</a>
                        </div>
                    ) : (
                        <div className="font-bold">❌ Mã không tồn tại</div>
                    )}
                </div>
            )}
         </div>

         {/* Print Action */}
         <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
             <h3 className="font-bold text-gray-800 mb-4">In Tem ({selectedPhotos.size})</h3>
             <div className="bg-yellow-50 text-yellow-800 text-xs p-3 rounded-lg mb-4 border border-yellow-200">
                 Kích thước tem: <strong>14mm x 21mm</strong>.<br/>
                 Tự động dàn trang in.
             </div>

             {isPrinting ? (
                 <button onClick={() => setIsPrinting(false)} className="w-full py-3 bg-red-500 text-white rounded-xl font-bold shadow hover:bg-red-600 transition">
                     Đóng chế độ in
                 </button>
             ) : (
                 <button 
                    onClick={handlePrint}
                    disabled={selectedPhotos.size === 0}
                    className="w-full py-3 bg-brand-600 text-white rounded-xl font-bold shadow-lg hover:bg-brand-700 transition disabled:bg-gray-400 disabled:shadow-none"
                 >
                     In Ngay
                 </button>
             )}
         </div>
      </div>

      {/* PRINT PORTAL */}
      {isPrinting && createPortal(
          <div className="qr-print-container">
              {/* Force Grid layout for stickers */}
              <div className="qr-sticker-sheet">
                {Array.from(selectedPhotos).map(id => {
                    const m = mappings[id];
                    if (!m) return null; // Should not happen if selected
                    const link = resolveCodeToLink(m.code);
                    if (!link) return null;

                    return (
                        <div key={id} className="qr-sticker">
                            <div className="qr-sticker-inner">
                                <img src={getQRImageUrl(link)} className="qr-img" alt="QR" />
                                <div className="qr-code-text">{m.code}</div>
                            </div>
                        </div>
                    );
                })}
              </div>
          </div>,
          document.body
      )}
    </div>
  );
};

