        setIsSyncing(false);
        setSaveStatus('Lỗi URL');
        alert("Lỗi: URL Google Script không hợp lệ.");
        return;
    }

    saveConfig(form);
    onUpdateConfig(form);

    try {
        const success = await saveAppConfigToCloud(form);
        if (success) setSaveStatus('✔ Đã đồng bộ Cloud');
        else {
            setSaveStatus('⚠️ Đã lưu máy (Lỗi Cloud)');
            alert("Lưu cục bộ thành công nhưng lỗi đồng bộ Cloud.");
        }
    } catch (e) {
        setSaveStatus('❌ Lỗi mạng');
    } finally {
        setIsSyncing(false);
        setTimeout(() => setSaveStatus(''), 5000);
    }
  };

  return (
    <div className="h-full bg-slate-50 flex flex-col font-sans overflow-hidden">
      <header className="flex-none bg-white border-b border-gray-200 px-4 py-3 flex justify-between items-center shadow-sm z-20">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 bg-gradient-to-br from-brand-500 to-brand-700 text-white rounded-lg flex items-center justify-center font-bold text-lg shadow-md">A</div>
          <div className="leading-tight">
            <h1 className="font-bold text-gray-800 text-base">Quản trị</h1>
            <p className="text-[10px] text-gray-400 hidden sm:block">ID Photo Booth Pro</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className={`text-sm font-bold transition-all ${saveStatus ? 'text-green-600' : 'opacity-0'}`}>{saveStatus}</span>
          <button onClick={onExit} className="px-3 py-2 bg-gray-100 hover:bg-gray-200 text-gray-600 rounded-lg text-sm font-bold transition flex items-center gap-1">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1"></path></svg> Thoát
          </button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto scroll-smooth">
        <div className="max-w-7xl w-full mx-auto p-4 lg:p-6 grid grid-cols-1 lg:grid-cols-4 gap-6 lg:gap-8 items-start">
          <nav className="flex lg:flex-col gap-2 overflow-x-auto whitespace-nowrap pb-2 lg:pb-0 sticky top-0 z-10 bg-slate-50 lg:static -mx-4 px-4 lg:mx-0 lg:px-0 pt-2 lg:pt-0 scrollbar-hide">
            {[
              { id: 'system', label: 'Cấu hình hệ thống', icon: '⚙️' },
              { id: 'ai_beauty', label: 'AI & Làm đẹp', icon: '✨' },
              { id: 'qr_label', label: 'In tem QR', icon: '🏷️' },
              { id: 'security', label: 'Bảo mật', icon: '🔒' }
            ].map(tab => {
              const isActive = activeTab === tab.id;
              return (
                <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-shrink-0 flex items-center gap-2 px-4 py-3 rounded-xl font-bold transition-all duration-200 border ${isActive ? 'bg-white text-brand-600 shadow-sm border-brand-100' : 'bg-white lg:bg-transparent border-transparent text-gray-400 hover:text-gray-600'}`}>
                  <span>{tab.icon}</span> {tab.label}
                </button>
              )
            })}
          </nav>

          <div className="lg:col-span-3 space-y-8 pb-32">
            {activeTab === 'system' && (
              <AdminSystemTab 
                form={form} 
                setForm={setForm} 
                onChange={handleChange} 
              />
            )}
            {activeTab === 'ai_beauty' && (
              <AdminAIExtrasTab 
                form={form} 
                setForm={setForm} 
              />
            )}
            {activeTab === 'qr_label' && (
              <AdminQRLabelTab />
            )}
            {activeTab === 'security' && <AdminSecurityTab form={form} onChange={handleChange} />}
          </div>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 p-4 z-50 shadow-[0_-5px_20px_rgba(0,0,0,0.05)]">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <span className="text-xs font-bold text-gray-500">{isSyncing ? 'ĐANG ĐỒNG BỘ...' : 'HỆ THỐNG SẴN SÀNG'}</span>
          <button onClick={handleSave} disabled={isSyncing} className={`px-8 py-3 rounded-xl font-bold shadow-lg transition-all ${isSyncing ? 'bg-gray-300' : 'bg-brand-600 hover:bg-brand-700 text-white shadow-brand-500/30'}`}>
            {isSyncing ? 'Đang Lưu...' : 'Lưu Thay Đổi'}
          </button>
        </div>
      </div>

      <style>{`
        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
        .animate-fadeIn { animation: fadeIn 0.4s ease-out forwards; }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
      `}</style>
    </div>
  );
};

export default AdminDashboard;
